function getHighSchoolDefensiveOpportunity(match, physicalTruth) {
  if (typeof DefensiveOpportunityFoundation === "undefined") return null;
  const prior = match?.groundBallInPlayState;
  const samePhysical = prior?.physicalTruth?.identity === physicalTruth?.identity;
  const historical = samePhysical && (prior?.defensiveOpportunity || (prior?.defensiveAccess?.reachResolution
    ? { topologyVersion: "regulation-coarse-zones-v1" } : null));
  const responsibility = DefensiveOpportunityFoundation.deriveGroundResponsibility?.(physicalTruth,
    DefensiveOpportunityFoundation.FIRST_BASE_GROUND_TOPOLOGY_VERSION);
  // The classifier is shared by player and NPC assignments. Unchanged SS/2B
  // lanes keep their existing execution identities; saved lanes retain their version.
  const topologyVersion = historical ? historical.topologyVersion
    : responsibility?.primaryPosition === "1B" ? DefensiveOpportunityFoundation.FIRST_BASE_GROUND_TOPOLOGY_VERSION
      : responsibility?.primaryPosition === "3B" ? DefensiveOpportunityFoundation.GROUND_TOPOLOGY_VERSION : undefined;
  return DefensiveOpportunityFoundation.resolveDefensiveOpportunity({
    physicalTruth, activeRoster: match?.rosters?.[match.defenseTeam], topologyVersion
  });
}

function getHighSchoolReachAccess(match, physicalTruth, opportunity, defenderContext) {
  if (typeof DefensiveReachSecureFoundation === "undefined" || !opportunity?.supported) return null;
  const actor = TeamRosterFoundation.getCurrentDefender(match.rosters[match.defenseTeam], opportunity.primaryPosition);
  const source = actor.id === "player" ? player : actor;
  const adapted = getDefensiveSimulationCapability(source, opportunity.primaryPosition, match);
  const capabilities = { defenderId: actor.id,
    reaction: defenderContext.reaction ?? adapted.reaction,
    range: defenderContext.range ?? adapted.range,
    mobility: getOffensiveSimulationCapability(source).speed,
    fielding: defenderContext.fielding ?? defenderContext.catching ?? adapted.fielding,
    catching: defenderContext.catching ?? defenderContext.fielding ?? adapted.fielding };
  const reach = DefensiveReachSecureFoundation.resolveReach({ physicalTruth, opportunity,
    activeRoster: match.rosters[match.defenseTeam], capabilities, roll: defenderContext.reachRoll });
  return { ...DefensiveReachSecureFoundation.projectAccess(reach), secureCapabilities: capabilities };
}

function getHighSchoolPhysicalDefensePlayerContext(match, physicalTruth, defenderContext, options = {}) {
  const opportunity = getHighSchoolDefensiveOpportunity(match, physicalTruth);
  if (!opportunity) return defenderContext; // Pre-foundation isolated harness compatibility.
  if (opportunity.bindingStatus === "invalid") throw new Error("Active defense integrity failed: defensive opportunity binding");
  const ownsGroundSlice = opportunity.supported && opportunity.primaryDefenderId === "player"
    && (opportunity.primaryPosition === "2B" || (["SS", "3B", "1B"].includes(opportunity.primaryPosition) && physicalTruth.ballType === "groundBall"));
  const firstBase = TeamRosterFoundation.getCurrentDefender(match.rosters[match.defenseTeam], "1B");
  const continuation = options.incomingContinuation;
  const liveContinuation = continuation?.version === "incoming-continuation-admission-v1"
    && continuation.matchId === match.id && continuation.batterId === match.currentBatter
    && continuation.inning === match.inning && continuation.half === match.half
    && continuation.offenseTeam === match.offenseTeam && continuation.defenseTeam === match.defenseTeam
    && continuation.outs === match.outs && JSON.stringify(continuation.runners) === JSON.stringify(match.runners);
  const receivesGroundSlice = firstBase?.id === "player" && physicalTruth.ballType === "groundBall"
    && liveContinuation && opportunity.supported && ["SS", "2B", "3B"].includes(opportunity.primaryPosition);
  const npc = receivesGroundSlice ? TeamRosterFoundation.getCurrentDefender(match.rosters[match.defenseTeam], opportunity.primaryPosition) : null;
  const acquisition = npc ? getDefensiveSimulationCapability(npc, npc.position, match) : defenderContext;
  return { ...defenderContext, ...acquisition, playerPosition: ownsGroundSlice || receivesGroundSlice ? TeamRosterFoundation.POSITION_LABELS[opportunity.primaryPosition] : "",
    defensiveOpportunity: opportunity,
    ...(ownsGroundSlice || receivesGroundSlice ? { reachAccess: getHighSchoolReachAccess(match, physicalTruth, opportunity, acquisition) } : {}) };
}

function ensureHighSchoolOrdinaryGroundBallInPlayHandoff(match, options = {}) {
  if (!match || typeof BattedBallGroundDefense === "undefined" || typeof OffensivePlateApproach === "undefined") return null;
  if (match.offensiveTacticalActionState?.selectedTacticalAction !== "standardAttack") return null;
  const playerPosition = match.developmentPositionOverride || getHighSchoolInfieldAssignmentPosition(match, player);
  const batter = getHighSchoolMatchSimulationEntity(match, match.currentBatter);
  const paIdentity = `${createHighSchoolOffensiveTacticalIdentity(match)}|ordinary-contact`;
  const existing = BattedBallGroundDefense.normalizeHandoff(match.groundBallInPlayState);
  const existingLineDrive = typeof BattedBallLineDriveDefense !== "undefined"
    ? BattedBallLineDriveDefense.normalizeCatchState(match.lineDriveCatchState) : null;
  const existingFlyBall = typeof BattedBallFlyBallDefense !== "undefined"
    ? BattedBallFlyBallDefense.normalizeFlyBallCatchState(match.flyBallCatchState) : null;
  if (existing?.identity === `${paIdentity}|ground-defense`) {
    validateHighSchoolReceiverSourceMetadata(match);
    if (existing.supported && !existing.settlementApplied) assertHighSchoolGroundParticipant(match);
    match.groundBallInPlayState = existing;
    return existing;
  }
  if (existingLineDrive?.identity === `${paIdentity}|line-drive-catch`) {
    if (existingLineDrive.supported && !existingLineDrive.settlementApplied) assertHighSchoolDetailedResponsibility(match, existingLineDrive.physicalTruth, "2B", "player");
    match.lineDriveCatchState = existingLineDrive;
    return null;
  }
  if (existingFlyBall?.identity === `${paIdentity}|fly-ball-catch`) {
    if (existingFlyBall.supported && !existingFlyBall.settlementApplied) assertHighSchoolDetailedResponsibility(match, existingFlyBall.physicalTruth, existingFlyBall.defenderContext?.position, existingFlyBall.defenderContext?.defenderId);
    match.flyBallCatchState = existingFlyBall;
    return null;
  }
  const defender = {
    ...getDefensiveSimulationCapability(player, "內野手"),
    ...(options.situationOverrides?.playerCapabilities || {})
  };
  const physicalDefenderContext = physicalTruth => getHighSchoolPhysicalDefensePlayerContext(match, physicalTruth, {
    playerPosition, catching: defender.fielding, reaction: defender.reaction, range: defender.range
  }, options);
  const offense = getHighSchoolProvisionalOffensiveTacticalCapabilities(match);
  const initial = OffensivePlateApproach.createPlateAppearanceState({
    paIdentity,
    batterId: match.currentBatter,
    approach: "balancedAttack",
    context: { outs: match.outs, runners: match.runners.slice(), hasRunner: match.runners.some(Boolean) }
  });
  const fixture = options.ordinaryPlateAppearance || {};
  const pitch = fixture.pitch || { pitchLocationClass: "hitterPitch" };
  const pitchOptions = {
    recognitionRoll: fixture.recognitionRoll ?? 0,
    decisionRoll: fixture.decisionRoll ?? 0,
    contactRoll: fixture.contactRoll ?? 0,
    foulRoll: fixture.foulRoll ?? 1,
    physicalRolls: fixture.physicalRolls,
    outcomeRoll: fixture.outcomeRoll,
    physicalOutcomeResolver({ physicalTruth }) {
      const access = BattedBallGroundDefense.resolveGroundBallDefensiveAccess({
        physicalTruth,
        defenderContext: physicalDefenderContext(physicalTruth)
      });
      if (access.supported) return {
        result: "groundBallDefensePending",
        authority: "bbpB1PhysicalDefensePending",
        contactQuality: Number(physicalTruth.executionEvidence?.continuousContactScore) || 0,
        resolvedContact: null
      };
      if (typeof BattedBallLineDriveDefense !== "undefined") {
        const airborneContext = BattedBallLineDriveDefense.buildAirborneBallContext(physicalTruth);
        const catchAccess = airborneContext ? BattedBallLineDriveDefense.resolveCatchAccess({
          airborneContext,
          defenderContext: physicalDefenderContext(physicalTruth)
        }) : null;
        const catchWindow = catchAccess ? BattedBallLineDriveDefense.buildCatchTimingWindow({ airborneContext, defensiveAccess: catchAccess }) : null;
        if (catchAccess?.supported && catchWindow?.state !== "expired") return {
          result: "lineDriveCatchPending",
          authority: "bbpB2APhysicalCatchPending",
          contactQuality: Number(physicalTruth.executionEvidence?.continuousContactScore) || 0,
          resolvedContact: null
        };
      }
      if (typeof BattedBallFlyBallDefense !== "undefined") {
        const flyBallDefender = getHighSchoolFlyBallDefenderCatchContext(match, physicalTruth, options);
        const flyBallOpportunity = BattedBallFlyBallDefense.buildFlyBallCatchOpportunity({
          identity: `${paIdentity}|fly-ball-catch`, physicalTruth, runners: [], outs: match.outs,
          runnerEntities: [], defenderContext: flyBallDefender
        });
        if (flyBallOpportunity?.supported) return {
          result: "flyBallCatchPending",
          authority: "bbpB2B1PhysicalCatchPending",
          contactQuality: Number(physicalTruth.executionEvidence?.continuousContactScore) || 0,
          resolvedContact: null
        };
      }
      return null;
    }
  };
  const plateAppearanceState = OffensivePlateApproach.simulatePlateAppearance({
    state: initial,
    abilities: {
      observe: Number(offense.baseballIQ) || 5,
      baseballIQ: Number(offense.baseballIQ) || 5,
      ballSense: Number(offense.ballSense) || 5,
      batting: Number(offense.batting) || 5,
      power: Number(batter?.power) || Number(offense.batting) || 5,
      bats: batter?.bats || "R"
    },
    pitchSequence: [pitch],
    pitchOptions: [pitchOptions]
  });
  match.ordinaryDefensivePlateAppearanceState = JSON.parse(JSON.stringify(plateAppearanceState));
  const physicalTruth = plateAppearanceState.battedBallPhysicalTruth;
  const runnerEntities = match.runners.map((runnerId, index) => {
    if (!runnerId) return null;
    const entity = getHighSchoolMatchSimulationEntity(match, runnerId);
    return {
      runnerId,
      originBase: index + 1,
      speed: Number(entity?.speed) || 5,
      reaction: Number(entity?.reaction) || Number(entity?.defense) || 5,
      baseballIQ: Number(entity?.baseballIQ) || Number(entity?.decision) || 5
    };
  }).filter(Boolean);
  if (plateAppearanceState.result === "lineDriveCatchPending" && physicalTruth && typeof BattedBallLineDriveDefense !== "undefined") {
    match.groundBallInPlayState = null;
    match.flyBallCatchState = null;
    match.lineDriveCatchState = BattedBallLineDriveDefense.buildCatchOpportunity({
      identity: `${paIdentity}|line-drive-catch`,
      physicalTruth,
      runners: match.runners,
      outs: match.outs,
      runnerEntities,
      preContactRunnerStates: options.preContactRunnerStates || {},
      defenderContext: physicalDefenderContext(physicalTruth)
    });
    return null;
  }
  if (plateAppearanceState.result === "flyBallCatchPending" && physicalTruth && typeof BattedBallFlyBallDefense !== "undefined") {
    match.groundBallInPlayState = null;
    match.lineDriveCatchState = null;
    match.flyBallCatchState = BattedBallFlyBallDefense.buildFlyBallCatchOpportunity({
      identity: `${paIdentity}|fly-ball-catch`,
      physicalTruth,
      runners: match.runners,
      outs: match.outs,
      runnerEntities,
      preContactRunnerStates: options.preContactRunnerStates || {},
      defenderContext: getHighSchoolFlyBallDefenderCatchContext(match, physicalTruth, options)
    });
    return null;
  }
  if (plateAppearanceState.result !== "groundBallDefensePending" || !physicalTruth) {
    const ordinaryInfield = isInfieldDecisionFamilyPosition(match.developmentPositionOverride || match.playerFieldingAssignment || match.position);
    match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({
      version: BattedBallGroundDefense.VERSION,
      identity: `${paIdentity}|ground-defense`,
      sourceAuthority: "unsupportedOrdinaryContactLegacyFallback",
      physicalTruth: physicalTruth ? JSON.parse(JSON.stringify(physicalTruth)) : null,
      supported: false,
      ...(ordinaryInfield ? { fallbackAuthority: "existingOrdinaryPhysicalOutcome",
        defensiveOpportunity: physicalTruth ? getHighSchoolDefensiveOpportunity(match, physicalTruth) : null }
        : { fallbackAuthority: "existingSyntheticDefensiveContext" }),
      legacyFallbackResult: plateAppearanceState.result || ""
    });
    match.lineDriveCatchState = physicalTruth?.ballType === "lineDrive" && typeof BattedBallLineDriveDefense !== "undefined"
      ? BattedBallLineDriveDefense.buildCatchOpportunity({
        identity: `${paIdentity}|line-drive-catch`, physicalTruth, runners: match.runners, outs: match.outs,
        runnerEntities, preContactRunnerStates: options.preContactRunnerStates || {},
        defenderContext: physicalDefenderContext(physicalTruth)
      }) : null;
    match.flyBallCatchState = physicalTruth?.ballType === "flyBall" && typeof BattedBallFlyBallDefense !== "undefined"
      ? BattedBallFlyBallDefense.buildFlyBallCatchOpportunity({
        identity: `${paIdentity}|fly-ball-catch`, physicalTruth, runners: match.runners, outs: match.outs,
        runnerEntities, preContactRunnerStates: options.preContactRunnerStates || {},
        defenderContext: getHighSchoolFlyBallDefenderCatchContext(match, physicalTruth, options)
      }) : null;
    return match.groundBallInPlayState;
  }
  const forceState = BattedBallGroundDefense.deriveForceState({ runners: match.runners, outs: match.outs });
  match.lineDriveCatchState = null;
  match.flyBallCatchState = null;
  match.groundBallInPlayState = BattedBallGroundDefense.buildGroundBallDefensiveOpportunity({
    identity: `${paIdentity}|ground-defense`,
    physicalTruth,
    runners: match.runners,
    outs: match.outs,
    forceState,
    runnerEntities,
    batterRunner: { runnerId: match.currentBatter, speed: Number(batter?.speed) || 5 },
    preContactRunnerStates: options.preContactRunnerStates || {},
    defenderContext: physicalDefenderContext(physicalTruth)
  });
  const firstBaseContext = createHighSchoolFirstBaseContext(match, match.groundBallInPlayState, options);
  if (firstBaseContext) match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({
    ...match.groundBallInPlayState, defensiveOpportunity: getHighSchoolDefensiveOpportunity(match, physicalTruth), firstBaseContext });
  // Unique SOURCE-only admission owner. This runs before classification, lifecycle execution and the original sample.
  const sourceHandoff = match.groundBallInPlayState;
  const sourceApi = getHighSchoolReceiverSourceAdapter(match);
  const sourceOpportunity = sourceApi ? getHighSchoolDefensiveOpportunity(match, physicalTruth) : null;
  const sourceRoster = match.rosters?.[match.defenseTeam];
  const sourceSs = sourceApi && sourceRoster ? TeamRosterFoundation.getCurrentDefender(sourceRoster, "SS") : null;
  const sourceFirst = sourceApi && sourceRoster ? TeamRosterFoundation.getCurrentDefender(sourceRoster, "1B") : null;
  if (sourceApi && sourceHandoff.supported && !firstBaseContext
    && sourceHandoff.defensiveAccess?.playerPosition === "游擊手" && sourceOpportunity?.primaryPosition === "SS"
    && sourceSs?.id === "player" && sourceFirst?.id && sourceFirst.id !== "player"
    && match.outs >= 0 && match.outs < 3 && match.runners.every(r => !r)
    && sourceHandoff.runnerRealization?.batterRunner?.runnerId === match.currentBatter) {
    const source = sourceApi.createSnapshot({ beforeExecution: true,
      physical: { version: sourceApi.versions.physical, matchId: match.id, plateAppearanceId: plateAppearanceState.paIdentity,
        contactId: physicalTruth.identity, physicalIdentity: physicalTruth.identity, playId: sourceHandoff.identity },
      original: { outs: match.outs, bases: match.runners.slice(), defenseTeam: match.defenseTeam,
        thrower: { actorId: sourceSs.id, position: "SS", role: "player" }, receiver: { actorId: sourceFirst.id, position: "1B", role: "npc" },
        batterRunner: match.currentBatter, firstBaseObligation: { runnerId: match.currentBatter, base: "first", forceReason: "batterRunnerRequiredToFirst" },
        topologyVersion: sourceOpportunity.topologyVersion },
      capabilitySource: { adapterVersion: sourceApi.versions.adapter,
        thrower: JSON.parse(JSON.stringify(sourceHandoff.defensiveAccess.secureCapabilities)),
        receiver: Object.fromEntries(["defense", "speed", "arm", "contact"].map(k => [k, Number.isFinite(sourceFirst[k]) ? sourceFirst[k] : null])),
        reference: sourceHandoff.defensiveAccess.reachResolution.identity } });
    match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({ ...sourceHandoff, receiverSourceFormatVersion: source.formatVersion,
      receiverSourceSnapshot: source.snapshot, receiverSourcePin: source.pin });
    match.receiverSourceFormatVersion = source.formatVersion;
    match.receiverSourceAdmission = source;
    validateHighSchoolReceiverSourceMetadata(match);
  }
  return match.groundBallInPlayState;
}

function prepareHighSchoolDefensiveMomentFromSimulation(match, options = {}) {
  if (match.activeSituation
    && !MatchSituationLifecycle.canResumeSimulation(match.activeSituation)) return null;
  const opportunity = findHighSchoolMatchOpportunity(match, options.opportunityTraceId);
  const densityState = ensureHighSchoolMatchDecisionDensityState(match);
  const flowState = {
    momentIndex: match.momentIndex,
    currentMomentId: match.currentMomentId,
    simulationPhase: match.simulationPhase,
    currentDomain: match.currentDomain,
    currentAssignment: match.currentAssignment
  };
  const primaryDefensiveDecision = flowState.simulationPhase === "moment_1_resolved"
    && (densityState?.defensiveMeaningfulDecisionCount || 0) === 0;
  match.pendingDefensiveResumeState = {
    simulationPhase: primaryDefensiveDecision ? "moment_2_resolved" : flowState.simulationPhase,
    momentIndex: primaryDefensiveDecision ? 1 : flowState.momentIndex,
    currentMomentId: primaryDefensiveDecision ? highSchoolYearOneMomentIds[1] : flowState.currentMomentId,
    currentDomain: "flow",
    currentAssignment: flowState.currentAssignment
  };
  match.currentBatter = getHighSchoolMatchLineupBatter(match, match.offenseTeam)?.id || "";
  match.momentIndex = 1;
  match.currentMomentId = primaryDefensiveDecision ? highSchoolYearOneMomentIds[1]
    : `hs_y1_match_defense_${(densityState?.defensiveMeaningfulDecisionCount || 0) + 1}`;
  match.currentDomain = "defense";
  const offensiveTacticalState = prepareHighSchoolOffensiveTacticalAction(match, options);
  if (offensiveTacticalState) {
    advanceHighSchoolOffensiveTacticalReveal(match, options.tacticalRevealPhase || "lateReveal");
  } else {
    match.opponentTacticalTruth = {
      code: match.previousMomentDecision === "zone" ? "hitAndRun" : match.previousMomentDecision === "attack" ? "earlyBreak" : "shortSwing",
      targetRunnerId: match.runners[1] || match.runners[0] || match.runners[2] || ""
    };
  }
  const productionBunt = offensiveTacticalState && typeof OffensiveBuntExecution !== "undefined"
    ? resolveHighSchoolProductionBuntPitch(match, {
      ...(options.buntPitchOptions || {}),
      initialCount: options.buntInitialCount
    }) : null;
  if (productionBunt?.event) {
    match.momentIndex = flowState.momentIndex;
    match.currentMomentId = flowState.currentMomentId;
    match.simulationPhase = flowState.simulationPhase;
    match.currentDomain = flowState.currentDomain;
    match.currentAssignment = flowState.currentAssignment;
    match.pendingDefensiveResumeState = null;
    setHighSchoolCoachTacticalDirection(match);
    finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, productionBunt.event, productionBunt.status);
    return productionBunt.event;
  }
  const buntHandoff = productionBunt?.shouldBuildDefense ? ensureHighSchoolBuntBallInPlayHandoff(match) : null;
  const groundBallHandoff = !productionBunt && offensiveTacticalState?.selectedTacticalAction === "standardAttack"
    ? ensureHighSchoolOrdinaryGroundBallInPlayHandoff(match, options) : null;
  // Only this plate appearance's handoff may own a ground-ball lifecycle or apply guard.
  // A prior completed grounder must not suppress a later routine defensive settlement.
  match.groundBallInPlayState = groundBallHandoff;
  if (buntHandoff && !buntHandoff.supported) {
    if (buntHandoff.fallbackPresented !== true) {
      const fallbackText = buntHandoff.ballContext.downstreamSupport === "unsupportedPopBuntFallback"
        ? "短打形成小飛球，壘上跑者回頭確認球是否落地；本階段不預判接殺或離壘出局。"
        : `短打落在${buntHandoff.ballContext.physicalTruth.placement === "thirdBaseSide" ? "三壘側" : buntHandoff.ballContext.physicalTruth.placement === "firstBaseSide" ? "一壘側" : "投手附近"}；此守備位置尚未納入二壘手垂直切片。`;
      match.buntBallInPlayState = Object.freeze({ ...JSON.parse(JSON.stringify(buntHandoff)), fallbackPresented: true });
      const fallbackEvent = recordHighSchoolMatchSimulationEvent(match, {
        type: "buntDefensiveFallback", presentationImportance: "attention", inning: match.inning, half: match.half,
        assignment: fallbackText, presentation: fallbackText, outs: match.outs, scores: match.scores, runners: match.runners
      });
      match.momentIndex = flowState.momentIndex;
      match.currentMomentId = flowState.currentMomentId;
      match.simulationPhase = flowState.simulationPhase;
      match.currentDomain = flowState.currentDomain;
      match.currentAssignment = flowState.currentAssignment;
      match.pendingDefensiveResumeState = null;
      finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, fallbackEvent, "unsupported-bunt-defense");
      return fallbackEvent;
    }
    return null;
  }
  const lineDriveCatchOpportunity = typeof BattedBallLineDriveDefense !== "undefined"
    ? BattedBallLineDriveDefense.normalizeCatchState(match.lineDriveCatchState) : null;
  if (!productionBunt && lineDriveCatchOpportunity?.supported) {
    resolveHighSchoolLineDriveCatchOpportunity(match, options);
    const catchEvent = applyHighSchoolLineDriveCatchResolution(match);
    restoreHighSchoolMatchAfterDefensiveDecision(match, flowState.simulationPhase);
    match.currentDomain = "flow";
    setHighSchoolCoachTacticalDirection(match);
    finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, catchEvent, "routine-line-drive-catch");
    return catchEvent;
  }
  const flyBallCatchOpportunity = typeof BattedBallFlyBallDefense !== "undefined"
    ? BattedBallFlyBallDefense.normalizeFlyBallCatchState(match.flyBallCatchState) : null;
  if (!productionBunt && flyBallCatchOpportunity?.supported) {
    resolveHighSchoolFlyBallCatchOpportunity(match, options);
    const catchEvent = applyHighSchoolFlyBallCatchResolution(match);
    const tagUpSituation = createHighSchoolRunnerTagUpSituation(match);
    if (tagUpSituation?.admission?.admittedToPlayer && tagUpSituation.lifecycleState === "presented") {
      setHighSchoolCoachTacticalDirection(match);
      finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, catchEvent, "tag-up-decision-created");
      return catchEvent;
    }
    restoreHighSchoolMatchAfterDefensiveDecision(match, flowState.simulationPhase);
    match.currentDomain = "flow";
    setHighSchoolCoachTacticalDirection(match);
    finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, catchEvent, "routine-fly-ball-catch");
    return catchEvent;
  }
  if (groundBallHandoff && !groundBallHandoff.supported
    && isInfieldDecisionFamilyPosition(match.developmentPositionOverride || match.playerFieldingAssignment || match.position)) {
    // Preserve this PA's physical source for every assignment. Unsupported contact
    // cannot acquire a synthetic player primary merely by entering the infield family.
    const result = groundBallHandoff.legacyFallbackResult;
    const before = { inning: match.inning, half: match.half, outs: match.outs, scores: { ...match.scores }, runners: match.runners.slice() };
    const facts = applyHighSchoolSimulatedPlateAppearance(match, result, match.currentBatter, match.offenseTeam);
    const after = { inning: match.inning, half: match.half, outs: match.outs, scores: { ...match.scores }, runners: match.runners.slice() };
    const event = recordHighSchoolRoutinePlateAppearance(match, match.currentBatter, result, before, after,
      Math.max(0, after.scores[match.offenseTeam] - before.scores[match.offenseTeam]), {
        ...facts, physicalTruth: groundBallHandoff.physicalTruth, defensiveOpportunity: groundBallHandoff.defensiveOpportunity,
        outcomeAuthority: "existingOrdinaryPhysicalOutcome",
        eventClassification: "ordinaryPlay" });
    advanceHighSchoolMatchBattingOrder(match, match.offenseTeam);
    match.ordinaryDefensivePlateAppearanceState = OffensivePlateApproach.markResultApplied(match.ordinaryDefensivePlateAppearanceState);
    Object.assign(match, { momentIndex: flowState.momentIndex, currentMomentId: flowState.currentMomentId,
      simulationPhase: flowState.simulationPhase, currentDomain: flowState.currentDomain, currentAssignment: flowState.currentAssignment,
      pendingDefensiveResumeState: null, defensiveSituation: {}, positionDecisionFamily: "",
      playerEventClassification: "ordinaryPlay", decisionGate: null, decisionTension: "none" });
    match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({ ...groundBallHandoff, settlementApplied: true });
    assertHighSchoolMatchStateIntegrity(match, "ordinary-outside-player-physical-scope");
    finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, event, "outside-player-physical-scope");
    return event;
  }
  if (buntHandoff) match.ballContext = JSON.parse(JSON.stringify(buntHandoff.ballContext));
  else if (groundBallHandoff?.supported) match.ballContext = JSON.parse(JSON.stringify(groundBallHandoff.ballContext));
  else setHighSchoolDefensiveBallContext(match, options.ballContextType || "");
  match.currentAssignment = getHighSchoolDefensiveSituationText(match);
  const priorTier = match.completedMoments[0]?.tier;
  match.coachInstruction = priorTier === "strong"
    ? "前一段執行已建立信任；現在先讀出局數，再決定是否挑戰額外出局。"
    : priorTier === "mixed"
      ? "先把最穩定的守備出局處理乾淨，不讓壘況繼續擴大。"
      : "前一段結果不影響你的守備資格；這一球只看補位與最短合法出局。";
  if (isInfieldDecisionFamilyPosition(match.developmentPositionOverride || match.position)) {
    match.defensiveSituation = {};
    const buntOverrides = getHighSchoolBuntDefensiveSituationOverrides(buntHandoff);
    const groundBallOverrides = getHighSchoolGroundBallDefensiveSituationOverrides(groundBallHandoff);
    const physicalOverrides = buntOverrides || groundBallOverrides;
    buildInfieldMeaningfulMoment(match, player, physicalOverrides
      ? { ...(options.situationOverrides || {}), ...physicalOverrides }
      : options.situationOverrides || {});
    match.currentAssignment = getHighSchoolDefensiveSituationText(match);
  } else {
    match.positionDecisionFamily = "";
    match.currentFieldingPosition = "";
    match.defensiveSituation = {};
  }
  match.opponentAdjustment = "跑者與打者的準備動作出現變化；只呈現你在場上能看見的線索。";
  const legalChoices = getHighSchoolDefensiveMomentChoices(match);
  const classification = match.defensiveSituation?.familyId === "infield"
    ? classifyHighSchoolMatchDefensiveOpportunity(match, match.defensiveSituation, legalChoices, true)
    : Object.freeze({ eventClassification: "playerMeaningfulDecision", decisionTension: "meaningful", gate: null });
  match.playerEventClassification = classification.eventClassification;
  match.decisionTension = classification.decisionTension;
  match.decisionGate = classification.gate ? JSON.parse(JSON.stringify(classification.gate)) : null;
  applyHighSchoolMatchDefensiveDecisionDensity(match, classification.density, classification.eventClassification === "playerMeaningfulDecision");
  updateHighSchoolMatchDefensiveOpportunityFromSituation(match, opportunity, match.defensiveSituation, legalChoices, classification);
  setHighSchoolCoachTacticalDirection(match);
  createGroundBallMatchSituation(match, legalChoices, classification, opportunity);
  if (classification.eventClassification === "playerRoutinePlay") {
    beginAutomaticGroundBallSituationExecution(match);
    const resolution = resolveRoutineDefensivePlay(match, match.defensiveSituation, options.randomSource ?? null, {
      densitySuppressed: classification.density?.meaningfulCandidate === true && classification.density?.allowed === false
    });
    if (!resolution) {
      if (typeof MatchSituationLifecycle !== "undefined"
        && match.activeSituation?.type === MatchSituationLifecycle.TYPES.groundBallDefensiveDecision) {
        abandonActiveMatchSituation(match, "noRoutineResolution");
      }
      match.momentIndex = flowState.momentIndex;
      match.currentMomentId = flowState.currentMomentId;
      match.simulationPhase = flowState.simulationPhase;
      match.currentDomain = flowState.currentDomain;
      match.currentAssignment = flowState.currentAssignment;
      match.pendingDefensiveResumeState = null;
      setHighSchoolCoachTacticalDirection(match);
      finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, null, "no-routine-resolution");
      return null;
    }
    recordGroundBallSituationResolution(match, resolution);
    const event = applyRoutineDefensiveResolutionToHighSchoolMatch(match, resolution);
    restoreHighSchoolMatchAfterDefensiveDecision(match, flowState.simulationPhase);
    match.currentDomain = "flow";
    setHighSchoolCoachTacticalDirection(match);
    finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, event, "routine");
    return event;
  }
  match.simulationPhase = "moment_2_ready";
  const event = recordHighSchoolMatchSimulationEvent(match, {
    type: "meaningfulMomentReached", eventClassification: "playerMeaningfulDecision", decisionTension: classification.decisionTension, inning: match.inning, half: match.half,
    momentId: match.currentMomentId, domain: match.currentDomain, assignment: match.currentAssignment,
    outs: match.outs, scores: match.scores, runners: match.runners
  });
  finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, event, "decision-created");
  return event;
}

function binding(input) {
  const saved = input.opportunity;
  const fresh = Opportunity.resolveDefensiveOpportunity({ physicalTruth: input.physicalTruth, activeRoster: input.activeRoster,
    topologyVersion: input.topologyVersion || saved?.topologyVersion || Opportunity.TOPOLOGY_VERSION });
  if (!fresh.supported || !saved || JSON.stringify(fresh) !== JSON.stringify(saved)
    || input.capabilities?.defenderId !== fresh.primaryDefenderId) {
    throw new Error("Reach / Secure integrity failed: invalid or stale opportunity / active defender");
  }
  return fresh;
}

function demand(opportunity) {
  const ball = opportunity.ballContext;
  const ambiguity = { clear: 0, sharedEdge: 0.3, coarseAmbiguity: 0.6 }[opportunity.responsibilityClassification];
  const pace = { weak: 2.5, moderate: 3.5, firm: 4.5, hard: 6 }[ball.pace];
  const airborne = ball.ballType !== "groundBall";
  const thirdBase = ball.ballType === "groundBall" && opportunity.primaryPosition === "3B";
  const reactionDemand = ball.ballType === "lineDrive" ? pace + ({ shallow: 2, medium: 0.5, deep: 0 }[ball.depth])
    : ball.ballType === "flyBall" ? pace * 0.5 : pace + (thirdBase && ball.pace === "hard" ? 1 : 0);
  // The near-line lane is closer to 3B; SS retains the greater nominal range.
  const groundMovement = thirdBase ? (ball.pace === "weak" ? 4 : 2) : (ball.pace === "weak" ? 4.5 : 3);
  const movementDemand = (airborne ? { shallow: 3, medium: 4, deep: 5 }[ball.depth]
    : groundMovement) + ambiguity + (thirdBase ? 0.5 : 0);
  const reactionWeight = ball.ballType === "flyBall" ? 0.3 : ball.ballType === "lineDrive" ? 0.6 : thirdBase ? 0.65 : 0.55;
  return { ...copy(ball), responsibilityClassification: opportunity.responsibilityClassification,
    ambiguity, reactionDemand, movementDemand, reactionWeight,
    reachDemand: round(reactionDemand * reactionWeight + movementDemand * (1 - reactionWeight)),
    units: "coarseRelativeDemand" };
}

function variation(stage, identity, explicitRoll) {
  const namespace = RNG_NAMESPACES[stage];
  const roll = Number.isFinite(explicitRoll) ? Math.max(0, Math.min(1, explicitRoll))
    : Physical.deterministicUnit(namespace, identity, stage);
  return { namespace, identity, roll, adjustment: round((0.5 - roll) * 2), consumed: true };
}

function resolveReach(input = {}) {
  const op = binding(input);
  const identity = `${op.identity}|${op.primaryDefenderId}|reach-v1`;
  const ballDemand = demand(op);
  const caps = input.capabilities;
  const inputs = { reaction: ability(caps.reaction), range: ability(caps.range), mobility: ability(caps.mobility ?? caps.range) };
  const movement = inputs.range * 0.75 + inputs.mobility * 0.25;
  const variationIdentity = `${op.executionIdentity || op.identity}|${op.primaryDefenderId}|reach-v1`;
  const evidence = variation("reach", variationIdentity, input.roll);
  const margin = round(inputs.reaction * ballDemand.reactionWeight + movement * (1 - ballDemand.reactionWeight)
    - ballDemand.reachDemand + evidence.adjustment);
  return freeze({ version: VERSION, identity, opportunityIdentity: op.identity, physicalIdentity: op.physicalIdentity,
    defenderId: op.primaryDefenderId, position: op.primaryPosition, supported: true,
    authority: "physicalOpportunity+activeDefender+reachCapabilities",
    reachDemand: ballDemand.reachDemand, reactionDemand: ballDemand.reactionDemand, movementDemand: ballDemand.movementDemand,
    responsibilityClassification: op.responsibilityClassification, ballDemand, inputs, margin,
    reached: margin >= 0, reachQuality: margin >= 1.25 ? "cleanArrival" : margin >= 0 ? "stretchedArrival" : "notReached",
    variationEvidence: evidence });
}

function projectAccess(reach) {
  const supported = reach?.supported === true && reach.reached === true;
  const level = !supported ? "unsupported" : reach.reachQuality === "cleanArrival" ? "favored" : "possible";
  return freeze({ supported, level, score: level === "favored" ? 3 : supported ? 2 : 0,
    reason: supported ? "canonicalReachArrival" : "canonicalReachUnavailable", reachIdentity: reach?.identity || "",
    reachResolution: reach ? copy(reach) : null });
}

function resolveGroundBallDefensiveAccess(input = {}) {
  const truth = input.physicalTruth || {};
  const defender = input.defenderContext || {};
  const shortstop = defender.playerPosition === "游擊手";
  const thirdBase = defender.playerPosition === "三壘手";
  const firstBase = defender.playerPosition === "一壘手";
  const opportunity = defender.defensiveOpportunity;
  const classified = Boolean(Opportunity && [Opportunity.GROUND_TOPOLOGY_VERSION, Opportunity.FIRST_BASE_GROUND_TOPOLOGY_VERSION].includes(opportunity?.topologyVersion));
  const responsibility = classified ? Opportunity.deriveGroundResponsibility(truth, opportunity.topologyVersion) : null;
  const playerPosition = shortstop ? "SS" : thirdBase ? "3B" : firstBase ? "1B" : defender.playerPosition === "二壘手" ? "2B" : "";
  const classificationMatches = responsibility && opportunity.supported
    && opportunity.physicalIdentity === truth.identity
    && JSON.stringify(opportunity.groundResponsibility) === JSON.stringify(responsibility)
    && opportunity.primaryPosition === responsibility.primaryPosition;
  const directionSupported = classified ? classificationMatches && responsibility.primaryPosition === playerPosition
    : shortstop ? ["leftSide", "middle"].includes(truth.direction) : truth.direction === "rightSide";
  const positionSupported = shortstop || defender.playerPosition === "二壘手" || (thirdBase || firstBase) && classified;
  const classificationFacts = classified && classificationMatches ? {
    topologyVersion: opportunity.topologyVersion, groundResponsibility: clone(responsibility)
  } : {};
  if (truth.ballType !== "groundBall" || !directionSupported || !positionSupported) {
    return deepFreeze({ playerPosition: defender.playerPosition || "", level: "unsupported", supported: false, score: 0, reason: truth.direction === "leftSide" ? "leftSideNoPlayerBallMagnet" : "unsupportedScope" });
  }
  if (defender.reachAccess) return deepFreeze({ playerPosition: defender.playerPosition, ...clone(defender.reachAccess), ...classificationFacts });
  const reaction = clamp(defender.reaction, 0, 20, 5);
  const range = clamp(defender.range, 0, 20, 5);
  const paceAdjustment = truth.pace === "hard" ? (reaction - 5) * 0.1
    : truth.pace === "weak" ? (range - 5) * 0.1 - 0.2
      : truth.pace === "firm" ? 0.25 : 0;
  const score = clamp(2.2 + (reaction - 5) * 0.08 + (range - 5) * 0.08 + paceAdjustment, 0, 4, 0);
  const level = score >= 3 ? "favored" : score >= 2 ? "possible" : score >= 1 ? "poor" : "unsupported";
  return deepFreeze({
    playerPosition: defender.playerPosition,
    ...classificationFacts,
    level,
    supported: level !== "unsupported",
    score: Math.round(score * 1000) / 1000,
    reason: level === "favored" ? "physicalAccessFavored" : level === "possible" ? "physicalAccessPossible" : "physicalAccessDifficult",
    inputs: { direction: truth.direction, pace: truth.pace, reaction, range }
  });
}

function resolveFairContactBallInPlay(state, pitch, abilities, recognition, options = {}) {
  const identity = `${state.paIdentity}|pitch-${state.pitchNumber + 1}`;
  const swingIntent = options.swingIntent || state.swingIntent;
  const physicalTruth = BattedBallPhysical ? BattedBallPhysical.resolveBattedBallPhysicalTruth({
    identity,
    actualPitch: pitch,
    recognition,
    action: "swing",
    contact: true,
    swingIntent,
    bats: abilities.bats || "R",
    abilities: { batting: abilities.batting, power: abilities.power },
    rolls: options.physicalRolls
  }) : null;
  const physicalOutcome = physicalTruth && typeof options.physicalOutcomeResolver === "function"
    ? options.physicalOutcomeResolver({ physicalTruth, state, pitch, abilities, recognition }) : null;
  let outcome;
  if (physicalOutcome?.result && /Pending$/.test(physicalOutcome.result)) {
    outcome = deepFreeze({ ...clone(physicalOutcome), adapterAuthority: physicalOutcome.authority || "physicalOutcomeResolver" });
  } else if (physicalTruth) {
    if (!OutcomeMapping) throw new Error("Physical BIP requires BattedBallOutcomeMapping");
    const official = OutcomeMapping.resolveOfficialBallInPlayOutcome({
      physicalTruth,
      defenseOutcome: physicalOutcome?.result ? { ...physicalOutcome, authority: physicalOutcome.authority || "physicalOutcomeResolver", settled: true, physicalIdentity: physicalTruth.identity } : physicalOutcome,
      rolls: { ...options.mappingRolls, ...(options.outcomeRoll !== undefined && options.mappingRolls?.hit === undefined ? { hit: options.outcomeRoll } : {}) }
    });
    outcome = deepFreeze({ ...official, adapterAuthority: official.authority,
      contactQuality: physicalTruth.executionEvidence.continuousContactScore, resolvedContact: official.trace.hitScore });
  } else outcome = resolveLegacyBallInPlayOutcome({ ...state, swingIntent }, pitch, abilities, recognition, null, options.outcomeRoll);
  return deepFreeze({ physicalTruth, outcome });
}

